def walk(root: str, path: str = '',
         exclude_files: Set[str] = frozenset(),
         exclude_dirs: Set[str] = frozenset()) -> Iterator[pathlib.Path]:
    with os.scandir(os.path.join(root, path)) as entries:
        for entry in entries:
            filepart = os.path.normpath(os.path.join(path, entry.name))
            if entry.is_dir():
                if filepart in exclude_dirs:
                    continue
                yield from walk(root, os.path.join(path, entry.name), exclude_files, exclude_dirs)
            else:
                if filepart in exclude_files:
                    continue
                yield pathlib.Path(path, entry.name)


