def get_available_from_port_range(from_port, to_port):
    """Returns available local port number.
    """
    r = range(from_port, to_port)

    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)

    for port in r:
        try:
            if sock.connect_ex(('localhost', port)) != 0:
                return port
        finally:
            sock.close()

